// SelfLearn · Curso 02 · English B1 → C2, hecho para Renzo: hispanohablante, logística e inventario,
// transición a análisis/ingeniería de datos y objetivo de trabajar en un entorno internacional (p. ej. Suiza).
// Ruta MCER orientativa: no certifica nivel. Para acreditarlo: Cambridge B2 First / C1 Advanced / C2 Proficiency o IELTS.
// Formato compacto: palabras y frases "inglés|español"; diálogo "Quién: inglés|español".
const U = (id, level, topic, title, goal, words, sentences, grammar, dialogue = []) => ({
  id, level, topic, title, goal,
  words: words.map(w => w.split("|")),
  sentences: sentences.map(s => s.split("|")),
  grammar: { title: grammar[0], text: grammar[1] },
  dialogue: dialogue.map(line => { const i = line.indexOf(": "), [nl, es] = line.slice(i + 2).split("|"); return { who: line.slice(0, i), t: nl, es }; })
});

export const EN_LEVELS = [
  { id: "B1", name: "Consolidación", goal: "Hablar de experiencia, rutinas y problemas con fluidez y menos errores típicos del español.", exam: "MCER B1 · Cambridge B1 Preliminary" },
  { id: "B2", name: "Inglés de trabajo", goal: "Reuniones, correos, entrevistas y explicar datos con seguridad.", exam: "MCER B2 · Cambridge B2 First" },
  { id: "C1", name: "Profesional avanzado", goal: "Negociar, presentar análisis complejos y escribir con matiz.", exam: "MCER C1 · Cambridge C1 Advanced / IELTS 7" },
  { id: "C2", name: "Dominio", goal: "Precisión, registro, ironía y estilo casi nativo.", exam: "MCER C2 · Cambridge C2 Proficiency" }
];

